CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '' CHECK (length(full_name)<=100), x_handle text NOT NULL DEFAULT '' CHECK (length(x_handle)<=50), country text NOT NULL DEFAULT '' CHECK (length(country)<=100), telegram text NOT NULL DEFAULT '' CHECK (length(telegram)<=50), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_creator_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER creator_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_creator_profile();
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE PRIMARY KEY, role text NOT NULL CHECK (role='admin'));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_creator_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'); $$;
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, email text NOT NULL CHECK(length(email)<=255 AND email LIKE '%@%'), vision text NOT NULL CHECK(length(vision) BETWEEN 10 AND 500), creator_type text NOT NULL CHECK(creator_type IN ('Creator','Developer','Business Owner','Community Admin','Affiliate Marketer','Trader','Other')), interests text[] NOT NULL CHECK(cardinality(interests) BETWEEN 1 AND 7 AND interests <@ ARRAY['Memes','Video','Music','Product Reviews','Global Content','Distribution','Automation']::text[]), intended_use text NOT NULL CHECK(intended_use IN ('Personal','Business','Community','Client Work')), source text NOT NULL CHECK(length(source) BETWEEN 1 AND 100), referral text NOT NULL DEFAULT '' CHECK(length(referral)<=50), consent boolean NOT NULL CHECK(consent=true), status text NOT NULL DEFAULT 'Submitted' CHECK(status IN ('Submitted','Under Review','Approved','Declined')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.applications TO authenticated;
GRANT UPDATE(status) ON public.applications TO authenticated;
GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_application_read ON public.applications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_creator_admin());
CREATE POLICY own_application_insert ON public.applications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Submitted');
CREATE POLICY admin_review ON public.applications FOR UPDATE TO authenticated USING(public.is_creator_admin()) WITH CHECK(public.is_creator_admin());
CREATE TABLE public.application_drafts (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, data jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(octet_length(data::text)<=10000), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.application_drafts TO authenticated;
GRANT ALL ON public.application_drafts TO service_role;
ALTER TABLE public.application_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_draft ON public.application_drafts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());